// Icons array - placeholder for all icons
icon_t icons[16] = {0};

// Initialize icons
void icons_init(void) {
    icons[ICON_COMPUTER].width = 32;
    icons[ICON_COMPUTER].height = 32;
    for (int i = 0; i < 32*32; i++) {
        icons[ICON_COMPUTER].data[i] = icon_computer[i];
    }
    
    icons[ICON_FOLDER].width = 32;
    icons[ICON_FOLDER].height = 32;
    for (int i = 0; i < 32*32; i++) {
        icons[ICON_FOLDER].data[i] = icon_folder[i];
    }
}

icon_t* icon_get(icon_id_t id) {
    if (id >= 0 && id < 16) {
        return &icons[id];
    }
    return 0;
}

void icon_draw(int x, int y, icon_id_t id) {
    icon_t* icon = icon_get(id);
    if (!icon) return;
    
    for (int py = 0; py < icon->height && py < ICON_SIZE; py++) {
        for (int px = 0; px < icon->width && px < ICON_SIZE; px++) {
            uint32_t color = icon->data[py * ICON_SIZE + px];
            if (color != 0x000000) {  // Don't draw black (transparent)
                draw_pixel(x + px, y + py, color);
            }
        }
    }
}